_BY_NAME = {p["name"]: p for p in PARAMETERS}

def get_parameter(name: str) -> dict[str, Any] | None:
    p = _BY_NAME.get(name)
    return dict(p) if p else None

def all_parameters() -> list[dict[str, Any]]:
    return [dict(p) for p in PARAMETERS]

def registry_summary() -> dict[str, Any]:
    domains: dict[str, int] = {}
    locked = 0
    for p in PARAMETERS:
        domains[p["domain"]] = domains.get(p["domain"], 0) + 1
        locked += int(bool(p["position_sensitive"]))
    return {
        "registry_version": REGISTRY_VERSION,
        "parameter_count": len(PARAMETERS),
        "position_sensitive_count": locked,
        "change_budget": CHANGE_BUDGET,
        "domains": domains,
        "execution_authority": "EVENT_DRIVEN_VALIDATED_AUTONOMOUS",
        "recommendation_mode": "AUTHORITY_TIERED",
    }


